-- GayanesV2: Migrate all 8 static PHP template pages into WordPress post_content
-- Safe to run in phpMyAdmin or mysql CLI on the live server.

-- Page: about-us
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- 1. Editorial Hero -->\n	<section class=\"gv2-about-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">About Us</span>\n			</nav>\n\n			<div class=\"gv2-about-hero__grid\">\n				<div class=\"gv2-about-hero__copy\">\n					<span class=\"gv2-eyebrow\">Our Story</span>\n					<h1 class=\"gv2-about-hero__title\">\n						Crafted with Love, Just Like Home					</h1>\n					<p class=\"gv2-about-hero__lead\">\n						From our family kitchen in Yerevan to your table — handcrafted Armenian semi-finished dishes made daily from 100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} natural local ingredients.					</p>\n					<div class=\"gv2-about-hero__actions\">\n						<a href=\"http://127.0.0.1:8088/shop/\" class=\"gv2-btn gv2-btn--primary gv2-btn--lg\">\n							Explore Menu						</a>\n						<a href=\"http://127.0.0.1:8088/contact/\" class=\"gv2-btn gv2-btn--glass gv2-btn--lg\">\n							Contact						</a>\n					</div>\n				</div>\n\n				<div class=\"gv2-about-hero__media\">\n					<div class=\"gv2-about-hero__arch\">\n													<img src=\"http://127.0.0.1:8088/wp-content/uploads/2026/11/springroll-banjareghenov-819x1024.jpg\" alt=\"Սպրինգ-ռոլլ բանջարեղենով\" class=\"gv2-about-hero__img\" loading=\"eager\" />\n											</div>\n\n					<div class=\"gv2-about-float-badge gv2-glass-card\">\n						<span class=\"gv2-about-float-badge__dot\" aria-hidden=\"true\"></span>\n						<span>100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} Natural &bull; No Preservatives</span>\n					</div>\n				</div>\n			</div>\n		</div>\n	</section>\n\n	<!-- 2. Trust &amp; Impact Metrics -->\n	<section class=\"gv2-section gv2-container\" aria-label=\"Our Kitchen Standards\">\n		<div class=\"gv2-about-stats\">\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}</span>\n				<span class=\"gv2-about-stat__label\">Natural Ingredients</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">0{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}</span>\n				<span class=\"gv2-about-stat__label\">Preservatives &amp; Additives</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">24/7</span>\n				<span class=\"gv2-about-stat__label\">Handcrafted Daily</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">15,000&#1423;+</span>\n				<span class=\"gv2-about-stat__label\">Free Yerevan Delivery</span>\n			</div>\n		</div>\n	</section>\n\n	<!-- 3. Brand Philosophy &amp; Editorial Story -->\n	<section class=\"gv2-section gv2-about-story-band\">\n		<div class=\"gv2-container gv2-about-story__grid\">\n			<div class=\"gv2-about-collage\" aria-hidden=\"true\">\n				<div class=\"gv2-about-collage__card gv2-about-collage__card--primary\">\n											<img src=\"http://127.0.0.1:8088/wp-content/uploads/2026/11/springroll-snkov-819x1024.jpg\" alt=\"Սպրինգ-ռոլլ սնկով\" loading=\"lazy\" />\n									</div>\n				<div class=\"gv2-about-collage__card gv2-about-collage__card--secondary\">\n											<img src=\"http://127.0.0.1:8088/wp-content/uploads/2026/11/springroll-snkov-819x1024.jpg\" alt=\"Սպրինգ-ռոլլ սնկով\" loading=\"lazy\" />\n									</div>\n			</div>\n\n			<div class=\"gv2-about-story__content\">\n				<span class=\"gv2-eyebrow\">Why Gayane’s Kitchen</span>\n				<h2 class=\"gv2-about-heading\">Tradition Meets Modern Convenience</h2>\n				<p class=\"gv2-about-text\">\n					We started Gayane’s Kitchen with a simple belief: busy days should never mean compromising on real, wholesome homemade food. Every dolma, pelmeni, khinkali, and blini is shaped by hand following time-honored family recipes.				</p>\n				<p class=\"gv2-about-text\">\n					We carefully select fresh farm meats, aromatic Armenian herbs, and natural dairy every morning, then gently chill our dishes so you can serve a warm, homemade dinner in just minutes.				</p>\n\n				<blockquote class=\"gv2-about-quote gv2-glass-card\">\n					<p>In our kitchen, every dish is prepared as if we are cooking for our own family.</p>\n					<footer>&mdash; Gayane, Founder &amp; Chef</footer>\n				</blockquote>\n			</div>\n		</div>\n	</section>\n\n	<!-- 4. Four Pillars of Craft -->\n	<section class=\"gv2-section gv2-container\" aria-labelledby=\"gv2-about-values-heading\">\n		<div class=\"gv2-about-center-head\">\n			<span class=\"gv2-eyebrow\">Crafted Like Home</span>\n			<h2 class=\"gv2-section__title\" id=\"gv2-about-values-heading\">Our Kitchen Standards</h2>\n		</div>\n\n		<div class=\"gv2-about-values\">\n			<article class=\"gv2-about-value gv2-glass-card\">\n				<div class=\"gv2-about-value__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Selected Farm Produce</h3>\n				<p>Only fresh meat, seasonal vegetables, and aromatic greens from trusted Armenian suppliers.</p>\n			</article>\n\n			<article class=\"gv2-about-value gv2-glass-card\">\n				<div class=\"gv2-about-value__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Authentic Family Recipes</h3>\n				<p>Hand-rolled dough and balanced spices passed down through generations without shortcuts.</p>\n			</article>\n\n			<article class=\"gv2-about-value gv2-glass-card\">\n				<div class=\"gv2-about-value__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Clean &amp; Certified Kitchen</h3>\n				<p>Strict hygiene standards at our Davtashen kitchen ensure safety and consistency in every batch.</p>\n			</article>\n\n			<article class=\"gv2-about-value gv2-glass-card\">\n				<div class=\"gv2-about-value__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Vegan &amp; Fasting Friendly</h3>\n				<p>Delicious plant-based falafel, potato and spinach vareniks, and veggie spring rolls crafted with care.</p>\n			</article>\n		</div>\n	</section>\n\n	<!-- 5. 3-Step Process -->\n	<section class=\"gv2-section gv2-container\" aria-labelledby=\"gv2-about-process-heading\">\n		<div class=\"gv2-about-center-head\">\n			<span class=\"gv2-eyebrow\">Chilled Delivery</span>\n			<h2 class=\"gv2-section__title\" id=\"gv2-about-process-heading\">From Our Kitchen to Your Table</h2>\n		</div>\n\n		<div class=\"gv2-about-steps\">\n			<div class=\"gv2-about-step gv2-glass-card\">\n				<span class=\"gv2-about-step__num\">01</span>\n				<h3>Handcrafted Daily</h3>\n				<p>Every morning our chefs prepare fresh fillings and hand-fold each piece with care.</p>\n			</div>\n\n			<div class=\"gv2-about-step gv2-glass-card\">\n				<span class=\"gv2-about-step__num\">02</span>\n				<h3>Gentle Shock Chilling</h3>\n				<p>Rapid chilling locks in natural taste, juiciness, and nutrients without any preservatives.</p>\n			</div>\n\n			<div class=\"gv2-about-step gv2-glass-card\">\n				<span class=\"gv2-about-step__num\">03</span>\n				<h3>Chilled Delivery in Yerevan</h3>\n				<p>Delivered straight to your home in temperature-controlled packaging — ready to cook in minutes.</p>\n			</div>\n		</div>\n	</section>\n\n	<!-- 6. Warm Brand CTA Band -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-about-cta\">\n			<div class=\"gv2-about-cta__copy\">\n				<h2>Ready for a Homemade Dinner in Minutes?</h2>\n				<p>Visit us in Davtashen or order online with same-day delivery across Yerevan.</p>\n				<div class=\"gv2-about-cta__meta\">\n					<a href=\"https://yandex.com/maps/-/CXSIyGZo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-about-cta__pill\">\n						\n						<span>Yerevan, Davtashen 2nd dist., 37</span>\n					</a>\n					<a href=\"tel:+37455600655\" class=\"gv2-about-cta__pill\">\n						\n						<span>+374 (55) 600655</span>\n					</a>\n				</div>\n			</div>\n			<div class=\"gv2-about-cta__actions\">\n				<a href=\"http://127.0.0.1:8088/shop/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-light\">\n					Explore Menu				</a>\n				<a href=\"http://127.0.0.1:8088/contact/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-outline\">\n					Contact				</a>\n			</div>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'about-us';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'about-us' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-about-us.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'about-us' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'about-us' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: contact
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- 1. Editorial Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Contact</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">Contact</span>\n				<h1 class=\"gv2-info-hero__title\">Get in Touch</h1>\n				<p class=\"gv2-info-hero__lead\">\n					Questions about our menu, delivery, or corporate orders? Our team in Yerevan is always happy to hear from you.				</p>\n			</div>\n		</div>\n	</section>\n\n	<!-- 2. Quick Contact Channels -->\n	<section class=\"gv2-section gv2-container\" aria-label=\"Contact\">\n		<div class=\"gv2-info-grid-4 gv2-contact-channels\">\n			<a href=\"tel:+37455600655\" class=\"gv2-info-card gv2-glass-card gv2-contact-channel\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<span class=\"gv2-contact-channel__label\">Բջջային / WhatsApp</span>\n				<strong class=\"gv2-contact-channel__val\">+374 (55) 600655</strong>\n			</a>\n\n			<a href=\"tel:+37411600111\" class=\"gv2-info-card gv2-glass-card gv2-contact-channel\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<span class=\"gv2-contact-channel__label\">Զանգերի կենտրոն</span>\n				<strong class=\"gv2-contact-channel__val\">+374 (11) 600111</strong>\n			</a>\n\n			<a href=\"mailto:info@gayanes.am\" class=\"gv2-info-card gv2-glass-card gv2-contact-channel\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<span class=\"gv2-contact-channel__label\">Էլ. փոստ</span>\n				<strong class=\"gv2-contact-channel__val\">info@gayanes.am</strong>\n			</a>\n\n			<a href=\"https://yandex.com/maps/-/CXSIyGZo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-info-card gv2-glass-card gv2-contact-channel\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<span class=\"gv2-contact-channel__label\">Խոհանոց</span>\n				<strong class=\"gv2-contact-channel__val\">Yerevan, Davtashen 2nd dist., 37</strong>\n			</a>\n		</div>\n	</section>\n\n	<!-- 3. Feedback Form + Kitchen Info &amp; Socials -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-contact-grid\">\n			<div class=\"gv2-contact-form-card gv2-glass-card\">\n				<h2>Send Us a Message</h2>\n\n				\n					[gv2_contact_nonce]\n					\n\n					<div class=\"gv2-contact-form__row\">\n						<div class=\"gv2-contact-field\">\n							<label for=\"gv2-cf-name\">Your Name *</label>\n							\n						</div>\n						<div class=\"gv2-contact-field\">\n							<label for=\"gv2-cf-contact\">Phone or Email *</label>\n							\n						</div>\n					</div>\n\n					<div class=\"gv2-contact-field\">\n						<label for=\"gv2-cf-topic\">Topic</label>\n						\n							Order &amp; Delivery\n							Corporate Partnership\n							Feedback &amp; Suggestions\n							Other Question\n						\n					</div>\n\n					<div class=\"gv2-contact-field\">\n						<label for=\"gv2-cf-message\">Message *</label>\n						<textarea id=\"gv2-cf-message\" name=\"message\" rows=\"5\"></textarea>\n					</div>\n\n					<div id=\"gv2-contact-feedback\" class=\"gv2-contact-feedback\" role=\"status\" aria-live=\"polite\" hidden></div>\n\n					<button type=\"submit\" class=\"gv2-btn gv2-btn--primary gv2-btn--lg gv2-contact-submit\">\n						Send Message &rarr;\n					</button>\n				\n			</div>\n\n			<aside class=\"gv2-contact-aside\">\n				<div class=\"gv2-info-card gv2-glass-card\">\n					<span class=\"gv2-info-card__badge\">Working Hours</span>\n					<h3>Daily: 09:00 – 21:00</h3>\n					<p>ք․ Երևան, 0054, Դավթաշեն 2-րդ թաղամաս, 37</p>\n					<p>Free delivery in Yerevan on orders over 15,000 AMD</p>\n					<div class=\"gv2-contact-aside__map\">\n						<a href=\"https://yandex.com/maps/-/CXSIyGZo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-btn gv2-btn--glass\">\n							Open on Map &rarr;\n						</a>\n					</div>\n				</div>\n\n				<div class=\"gv2-info-card gv2-glass-card\">\n					<span class=\"gv2-info-card__badge\">Messengers &amp; Socials</span>\n					<h3>Messengers &amp; Socials</h3>\n					<div class=\"gv2-contact-socials\">\n						<a href=\"https://wa.me/37455600655\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-contact-pill\">WhatsApp</a>\n						<a href=\"https://t.me/+37455600655\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-contact-pill\">Telegram</a>\n						<a href=\"//chat?number=+37455600655\" class=\"gv2-contact-pill\">Viber</a>\n						<a href=\"https://www.instagram.com/gayanes_kitchen\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-contact-pill\">Instagram</a>\n						<a href=\"https://www.facebook.com/gayanes.kitchen\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-contact-pill\">Facebook</a>\n					</div>\n				</div>\n			</aside>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'contact';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'contact' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-contact.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'contact' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'contact' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: faq
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- 1. Editorial Hero + Live Search &amp; Category Pills -->\n	<section class=\"gv2-faq-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Frequently Asked Questions</span>\n			</nav>\n\n			<div class=\"gv2-faq-hero__inner\">\n				<span class=\"gv2-eyebrow\">Questions &amp; Answers</span>\n				<h1 class=\"gv2-faq-hero__title\">Frequently Asked Questions</h1>\n				<p class=\"gv2-faq-hero__lead\">\n					Everything you need to know about Gayane’s Kitchen homemade Armenian semi-finished dishes, natural ingredients, cooking tips, and Yerevan delivery.				</p>\n\n				<!-- Frosted Glass Search Pill -->\n				<div class=\"gv2-faq-search gv2-glass-card\">\n					\n					<label class=\"gv2-sr-only\" for=\"gv2-faq-search-input\">Search questions...</label>\n					\n				</div>\n\n				<!-- Horizontal Scrollable Category Filter Pills -->\n				<div class=\"gv2-faq-cats\" role=\"tablist\" aria-label=\"Categories\">\n																	<button type=\"button\" role=\"tab\" class=\"gv2-faq-cat-pill is-active\" data-faq-cat=\"all\">\n							Բոլորը						</button>\n																	<button type=\"button\" role=\"tab\" class=\"gv2-faq-cat-pill\" data-faq-cat=\"quality\">\n							Որակ և բաղադրություն						</button>\n																	<button type=\"button\" role=\"tab\" class=\"gv2-faq-cat-pill\" data-faq-cat=\"delivery\">\n							Առաքում և վճարում						</button>\n																	<button type=\"button\" role=\"tab\" class=\"gv2-faq-cat-pill\" data-faq-cat=\"cooking\">\n							Պատրաստում և պահպանում						</button>\n																	<button type=\"button\" role=\"tab\" class=\"gv2-faq-cat-pill\" data-faq-cat=\"ordering\">\n							Պատվերներ և հատուկ մենյու						</button>\n									</div>\n			</div>\n		</div>\n	</section>\n\n	<!-- 2. FAQ Accordion List -->\n	<section class=\"gv2-section gv2-container\" aria-label=\"Frequently Asked Questions\">\n		<div class=\"gv2-faq-list\" id=\"gv2-faq-list\">\n											<details id=\"what-is-gayanes-kitchen\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"quality\" data-search=\"what does gayane’s kitchen (gayanes.am) offer and what dishes can i order? gayane’s kitchen (gayanes.am) is a yerevan-based artisanal kitchen crafting 100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} natural, handmade armenian semi-finished dishes daily. our menu includes homemade dolma, khinkali, pelmeni, blini, potato and spinach vareniks, falafel, and spring rolls with zero preservatives. որակ և բաղադրություն\" open>\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Որակ և բաղադրություն</span>\n														<h2 class=\"gv2-faq-item__q\">What does Gayane’s Kitchen (gayanes.am) offer and what dishes can I order?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Gayane’s Kitchen (gayanes.am) is a Yerevan-based artisanal kitchen crafting 100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} natural, handmade Armenian semi-finished dishes daily. Our menu includes homemade dolma, khinkali, pelmeni, blini, potato and spinach vareniks, falafel, and spring rolls with zero preservatives.</p>\n					</div>\n				</details>\n											<details id=\"yerevan-delivery-cost\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"delivery\" data-search=\"how does delivery work in yerevan and how much does it cost? gayane’s kitchen provides same-day chilled delivery across all of yerevan in temperature-controlled packaging. delivery in yerevan is free for orders of 15,000 amd or more. you can select your preferred delivery date and time slot directly at checkout. առաքում և վճարում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Առաքում և վճարում</span>\n														<h2 class=\"gv2-faq-item__q\">How does delivery work in Yerevan and how much does it cost?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Gayane’s Kitchen provides same-day chilled delivery across all of Yerevan in temperature-controlled packaging. Delivery in Yerevan is FREE for orders of 15,000 AMD or more. You can select your preferred delivery date and time slot directly at checkout.</p>\n					</div>\n				</details>\n											<details id=\"preservatives-natural\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"quality\" data-search=\"do your dishes contain preservatives, soy fillers, or artificial additives? no, never. every dish is made from 100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} natural, fresh local ingredients — selected armenian farm meat, seasonal vegetables, fresh herbs, and natural dairy. we use zero preservatives, flavor enhancers, or soy fillers; freshness is locked in solely through gentle rapid chilling. որակ և բաղադրություն\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Որակ և բաղադրություն</span>\n														<h2 class=\"gv2-faq-item__q\">Do your dishes contain preservatives, soy fillers, or artificial additives?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>No, never. Every dish is made from 100{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} natural, fresh local ingredients — selected Armenian farm meat, seasonal vegetables, fresh herbs, and natural dairy. We use zero preservatives, flavor enhancers, or soy fillers; freshness is locked in solely through gentle rapid chilling.</p>\n					</div>\n				</details>\n											<details id=\"cooking-time-storage\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"cooking\" data-search=\"how long do the dishes take to cook and how should they be stored? gayane’s kitchen dishes cook in just 5–12 minutes straight from the freezer — no thawing needed. store them sealed in your freezer at -18°c for up to 90 days, and cook directly in boiling water or a preheated pan. պատրաստում և պահպանում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատրաստում և պահպանում</span>\n														<h2 class=\"gv2-faq-item__q\">How long do the dishes take to cook and how should they be stored?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Gayane’s Kitchen dishes cook in just 5–12 minutes straight from the freezer — no thawing needed. Store them sealed in your freezer at -18°C for up to 90 days, and cook directly in boiling water or a preheated pan.</p>\n					</div>\n				</details>\n											<details id=\"vegan-fasting-options\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"ordering\" data-search=\"do you offer vegan, vegetarian, or armenian fasting options? yes! we offer a dedicated vegan and fasting-friendly selection, including potato vareniks, spinach vareniks, homemade falafel, vegetable and mushroom spring rolls, and meatless dolma — all prepared on clean surfaces without animal products. պատվերներ և հատուկ մենյու\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատվերներ և հատուկ մենյու</span>\n														<h2 class=\"gv2-faq-item__q\">Do you offer vegan, vegetarian, or Armenian fasting options?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Yes! We offer a dedicated vegan and fasting-friendly selection, including potato vareniks, spinach vareniks, homemade falafel, vegetable and mushroom spring rolls, and meatless dolma — all prepared on clean surfaces without animal products.</p>\n					</div>\n				</details>\n											<details id=\"kitchen-address-pickup\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"delivery\" data-search=\"where is gayane’s kitchen located and can i pick up my order in person? our kitchen is located in yerevan at davtashen 2nd district, 37 (0054). yes, you can place your order online and arrange self-pickup, or call us at +374 (55) 600655 or +374 (11) 600111. առաքում և վճարում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Առաքում և վճարում</span>\n														<h2 class=\"gv2-faq-item__q\">Where is Gayane’s Kitchen located and can I pick up my order in person?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Our kitchen is located in Yerevan at Davtashen 2nd District, 37 (0054). Yes, you can place your order online and arrange self-pickup, or call us at +374 (55) 600655 or +374 (11) 600111.</p>\n					</div>\n				</details>\n											<details id=\"payment-methods\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"delivery\" data-search=\"what payment methods are accepted on gayanes.am? you can pay cash on delivery or via online bank card / cashless payment at checkout. all prices are listed in armenian drams (amd). առաքում և վճարում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Առաքում և վճարում</span>\n														<h2 class=\"gv2-faq-item__q\">What payment methods are accepted on gayanes.am?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>You can pay cash on delivery or via online bank card / cashless payment at checkout. All prices are listed in Armenian Drams (AMD).</p>\n					</div>\n				</details>\n											<details id=\"how-to-boil-pelmeni-khinkali\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"cooking\" data-search=\"how should i boil pelmeni, khinkali, and vareniks so they don’t stick or tear? bring a generous pot of salted water to a boil, drop in the frozen pieces without thawing, and gently stir during the first 30 seconds. simmer on medium heat for 6–8 minutes for pelmeni and vareniks, and 10–12 minutes for khinkali. պատրաստում և պահպանում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատրաստում և պահպանում</span>\n														<h2 class=\"gv2-faq-item__q\">How should I boil pelmeni, khinkali, and vareniks so they don’t stick or tear?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Bring a generous pot of salted water to a boil, drop in the frozen pieces without thawing, and gently stir during the first 30 seconds. Simmer on medium heat for 6–8 minutes for pelmeni and vareniks, and 10–12 minutes for khinkali.</p>\n					</div>\n				</details>\n											<details id=\"how-to-cook-dolma-springrolls\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"cooking\" data-search=\"how do i cook dolma, blini, falafel, and spring rolls? simmer dolma covered with warm water or light tomato broth for 15–20 minutes. pan-fry blini, falafel, and spring rolls in preheated oil, or bake/air-fry at 190°c for 12–15 minutes until golden and crisp. պատրաստում և պահպանում\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատրաստում և պահպանում</span>\n														<h2 class=\"gv2-faq-item__q\">How do I cook dolma, blini, falafel, and spring rolls?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Simmer dolma covered with warm water or light tomato broth for 15–20 minutes. Pan-fry blini, falafel, and spring rolls in preheated oil, or bake/air-fry at 190°C for 12–15 minutes until golden and crisp.</p>\n					</div>\n				</details>\n											<details id=\"package-sizes-servings\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"ordering\" data-search=\"what are the package weights and how many servings are in one pack? most dishes come in convenient 400g to 1kg family packs (or by piece for khinkali and blini). one pack typically serves 2–4 people for a full homemade meal. exact weights are clearly shown on every product card. պատվերներ և հատուկ մենյու\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատվերներ և հատուկ մենյու</span>\n														<h2 class=\"gv2-faq-item__q\">What are the package weights and how many servings are in one pack?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Most dishes come in convenient 400g to 1kg family packs (or by piece for khinkali and blini). One pack typically serves 2–4 people for a full homemade meal. Exact weights are clearly shown on every product card.</p>\n					</div>\n				</details>\n											<details id=\"bulk-events-orders\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"ordering\" data-search=\"can i place bulk orders for family events, gatherings, or offices? yes! for bulk or event orders, please reach out at least 1 day in advance via +374 (55) 600655 or whatsapp / telegram, and we will prepare a fresh batch tailored to your gathering. պատվերներ և հատուկ մենյու\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Պատվերներ և հատուկ մենյու</span>\n														<h2 class=\"gv2-faq-item__q\">Can I place bulk orders for family events, gatherings, or offices?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Yes! For bulk or event orders, please reach out at least 1 day in advance via +374 (55) 600655 or WhatsApp / Telegram, and we will prepare a fresh batch tailored to your gathering.</p>\n					</div>\n				</details>\n											<details id=\"difference-from-supermarket\" class=\"gv2-faq-item gv2-glass-card\" data-category=\"quality\" data-search=\"how is gayane’s kitchen different from mass-produced supermarket frozen foods? unlike factory-made frozen foods, everything at gayane’s kitchen is handcrafted daily in small batches with thin homemade dough, generous fillings, and zero cheap fillers — giving you true home-cooked taste and texture. որակ և բաղադրություն\">\n					<summary class=\"gv2-faq-item__summary\">\n						<div class=\"gv2-faq-item__head\">\n															<span class=\"gv2-faq-item__tag\">Որակ և բաղադրություն</span>\n														<h2 class=\"gv2-faq-item__q\">How is Gayane’s Kitchen different from mass-produced supermarket frozen foods?</h2>\n						</div>\n						<span class=\"gv2-faq-item__toggle\" aria-hidden=\"true\">\n							\n						</span>\n					</summary>\n					<div class=\"gv2-faq-item__body\">\n						<p>Unlike factory-made frozen foods, everything at Gayane’s Kitchen is handcrafted daily in small batches with thin homemade dough, generous fillings, and zero cheap fillers — giving you true home-cooked taste and texture.</p>\n					</div>\n				</details>\n					</div>\n\n		<div id=\"gv2-faq-empty\" class=\"gv2-faq-empty gv2-glass-card\" hidden>\n			<p>No matching questions found. Try another keyword or contact us directly.</p>\n		</div>\n	</section>\n\n	<!-- 3. Still Have Questions? CTA Card -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-about-cta\">\n			<div class=\"gv2-about-cta__copy\">\n				<h2>Still Have Questions?</h2>\n				<p>Our team in Yerevan is happy to help with orders, ingredients, or special event requests.</p>\n				<div class=\"gv2-about-cta__meta\">\n					<a href=\"tel:+37455600655\" class=\"gv2-about-cta__pill\">\n						\n						<span>+374 (55) 600655</span>\n					</a>\n					<a href=\"https://wa.me/37455600655\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-about-cta__pill\">\n						<span>WhatsApp</span>\n					</a>\n					<a href=\"https://t.me/+37455600655\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"gv2-about-cta__pill\">\n						<span>Telegram</span>\n					</a>\n				</div>\n			</div>\n			<div class=\"gv2-about-cta__actions\">\n				<a href=\"http://127.0.0.1:8088/shop/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-light\">\n					Explore Menu				</a>\n				<a href=\"http://127.0.0.1:8088/contact/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-outline\">\n					Contact				</a>\n			</div>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'faq';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'faq' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-faq.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'faq' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'faq' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: delivery
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Առաքում և վճարում</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">Առաքման և վճարման պայմաններ</span>\n				<h1 class=\"gv2-info-hero__title\">Առաքում և վճարում</h1>\n				<p class=\"gv2-info-hero__lead\">\n					«Գայանեի Խոհանոց»-ի առաքման ծառայությունն ընդունում է պատվերներ ինչպես կայքի միջոցով, այնպես էլ <a href=\"tel:+37411600111\">011 600 111</a> հեռախոսահամարով՝ ապահովելով արագ, հարմարավետ և սառեցված առաքում Երևան քաղաքում։\n				</p>\n			</div>\n		</div>\n	</section>\n\n	<!-- Key Delivery Metrics -->\n	<section class=\"gv2-section gv2-container\" aria-label=\"Առաքման հիմնական պայմաններ\">\n		<div class=\"gv2-about-stats\">\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">ԱՆՎՃԱՐ</span>\n				<span class=\"gv2-about-stat__label\">15,000 ֏ և ավելի պատվերների համար</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">1,500 ֏</span>\n				<span class=\"gv2-about-stat__label\">15,000 ֏-ից ցածր պատվերների դեպքում</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">1–2 օր</span>\n				<span class=\"gv2-about-stat__label\">Առաքում Երևան քաղաքում</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">011 600 111</span>\n				<span class=\"gv2-about-stat__label\">Հեռախոսային պատվերների կենտրոն</span>\n			</div>\n		</div>\n	</section>\n\n	<!-- Delivery Details -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-section__head\">\n			<h2 class=\"gv2-section__title\">Առաքման պայմաններ</h2>\n		</div>\n\n		<div class=\"gv2-info-grid-2\">\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Ինչպես է իրականացվում առաքումը</h3>\n				<p>Կայքում ընտրում եք Ձեր նախընտրած ուտեստները, նշում առաքման հասցեն, հեռախոսահամարը, նախընտրելի օրն ու ժամանակահատվածը, ինչպես նաև հավելյալ ցուցումներ վարորդի համար (օրինակ՝ շենքի մուտքը կամ դուռը թակելու մասին)։</p>\n				<p>Մեր առաքիչը կապ կհաստատի Ձեզ հետ նշված հեռախոսահամարով՝ ճշտումներ կատարելու համար։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<div class=\"gv2-info-card__icon\" aria-hidden=\"true\">\n					\n				</div>\n				<h3>Պատվերի կարգավիճակ և փոփոխություն</h3>\n				<p>Կայք մուտք գործելուց հետո Ձեր անձնական էջում կարող եք հետևել պատվերների պատմությանը և կարգավիճակին՝ «Պատվիրված», «Հաստատված», «Առաքված», «Կատարված»։</p>\n				<ul class=\"gv2-info-list\">\n					<li>Մեկ պատվերի շրջանակներում ապրանքն առաքվում է մեկ հասցեով։</li>\n					<li>Տարբեր հասցեների համար խնդրում ենք ձևակերպել առանձին պատվերներ։</li>\n					<li>Պատվերին լրացուցիչ ապրանք ավելացնելու համար զանգահարեք <a href=\"tel:+37411600111\">011 600 111</a>։</li>\n				</ul>\n			</article>\n		</div>\n	</section>\n\n	<!-- Payment Methods -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-section__head\">\n			<h2 class=\"gv2-section__title\">Վճարման եղանակներ</h2>\n		</div>\n\n		<div class=\"gv2-info-grid-3\">\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Առաքման պահին</span>\n				<h3>Կանխիկ վճարում</h3>\n				<p>Վճարում եք պատվերը ստանալիս՝ կանխիկ ՀՀ դրամով։ Առաքիչը տրամադրում է ՀԴՄ կտրոն (անհրաժեշտության դեպքում՝ նաև հաշիվ-ապրանքագիր)։ Պատվիրելիս կարող եք նշել մանրի անհրաժեշտությունը։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Առցանց</span>\n				<h3>Բանկային քարտ (ArCa, Visa, MasterCard)</h3>\n				<p>Անվտանգ առցանց վճարում անմիջապես կայքում՝ ArCa, Visa և MasterCard բանկային քարտերով՝ ԱրՔա վճարային համակարգի միջոցով։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Էլեկտրոնային դրամապանակ</span>\n				<h3>Idram</h3>\n				<p>Պատվերի ձևակերպման «Վճարում» քայլում ընտրեք ԻԴՐԱՄ-ը և կատարեք արագ վճարում ՀՀ դրամով անմիջապես Ձեր ԻԴՐԱՄ հաշվից։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Բջջային վճարում</span>\n				<h3>Telcell Wallet</h3>\n				<p>Ընտրեք Telcell-ը վճարման քայլում և վճարեք Telcell Wallet-ի միջոցով՝ իրական ժամանակում և ցանկացած վայրից։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Իրավաբանական և ֆիզ. անձանց</span>\n				<h3>Բանկային փոխանցում</h3>\n				<p>Նախապես պայմանագիր կնքած կորպորատիվ հաճախորդները պատվերը ստանում են անմիջապես։ Առանց պայմանագրի դեպքում առաքումն իրականացվում է գումարը հաշվին հայտնվելուց հետո՝ հաշիվ-ապրանքագրով։</p>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">ՀՀ Օրենսդրություն</span>\n				<h3>Արժույթ և հարկեր</h3>\n				<p>Կայքում ներկայացված ապրանքների գները վերջնական են և ներառում են բոլոր հարկերը։ Դոլարով կամ այլ արտարժույթով կանխիկ վճարումներ չեն ընդունվում։</p>\n			</article>\n		</div>\n	</section>\n\n	<!-- CTA -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-about-cta\">\n			<div class=\"gv2-about-cta__copy\">\n				<h2>Կորպորատի՞վ պատվեր կամ լրացուցիչ հարցեր</h2>\n				<p>Կապվեք մեզ հետ կամ ուսումնասիրեք մեր կորպորատիվ հաճախորդների հատուկ պայմանները։</p>\n				<div class=\"gv2-about-cta__meta\">\n					<a href=\"tel:+37411600111\" class=\"gv2-about-cta__pill\">011 600 111</a>\n					<a href=\"tel:+37455600655\" class=\"gv2-about-cta__pill\">055 60 06 55</a>\n				</div>\n			</div>\n			<div class=\"gv2-about-cta__actions\">\n				<a href=\"http://127.0.0.1:8088/shop/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-light\">\n					Explore Menu				</a>\n				<a href=\"http://127.0.0.1:8088/corporate-clients/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-outline\">\n					Կորպորատիվ հաճախորդներին\n				</a>\n			</div>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'delivery';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'delivery' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-delivery.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'delivery' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'delivery' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: corporate-clients
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Կորպորատիվ հաճախորդների համար</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">B2B համագործակցություն</span>\n				<h1 class=\"gv2-info-hero__title\">Կորպորատիվ հաճախորդներին</h1>\n				<p class=\"gv2-info-hero__lead\">\n					«Գայանեի Խոհանոց»-ում գործում է հատուկ կորպորատիվ վաճառքների բաժին։ Իրավաբանական անձանց, գրասենյակների, սրճարանների և հաստատությունների սպասարկումն իրականացվում է կնքված պայմանագրի հիման վրա՝ արագ, հուսալի և շահավետ պայմաններով։\n				</p>\n				<div class=\"gv2-info-hero__actions\">\n					<a href=\"tel:+37455600655\" class=\"gv2-btn gv2-btn--primary gv2-btn--lg\">Զանգահարել՝ 055 60 06 55</a>\n					<a href=\"mailto:info@gayanes.am?subject={1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D4{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BF{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BA{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BF{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}AB{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BE{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B0{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B4{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A3{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}AE{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}AF{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}81{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}82{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A9{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}82{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B6\" class=\"gv2-btn gv2-btn--glass gv2-btn--lg\">Գրել էլ. փոստով</a>\n				</div>\n			</div>\n		</div>\n	</section>\n\n	<!-- Key Corporate Perks -->\n	<section class=\"gv2-section gv2-container\" aria-label=\"Կորպորատիվ առավելություններ\">\n		<div class=\"gv2-about-stats\">\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}</span>\n				<span class=\"gv2-about-stat__label\">Զեղչի քարտ (կուպոն) կորպորատիվ գործընկերներին</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">ԱՆՎՃԱՐ</span>\n				<span class=\"gv2-about-stat__label\">Առաքում Երևանի ողջ տարածքում</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">Ամսական</span>\n				<span class=\"gv2-about-stat__label\">Վճարում հաշիվ-ապրանքագրով՝ ամսվա վերջում կամ պատվերից հետո</span>\n			</div>\n			<div class=\"gv2-about-stat gv2-glass-card\">\n				<span class=\"gv2-about-stat__num\">Անհատական</span>\n				<span class=\"gv2-about-stat__label\">Կորպորատիվ վաճառքների մենեջերի աջակցություն</span>\n			</div>\n		</div>\n	</section>\n\n	<!-- Detailed Corporate Terms -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-info-grid-2\">\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Պայմանագրային սպասարկում</span>\n				<h2>Առանձնահատուկ պայմաններ գործընկերների համար</h2>\n				<ul class=\"gv2-info-list\">\n					<li><strong>Հաշիվ-ապրանքագրով վճարում.</strong> վճարումն իրականացվում է ամսվա վերջում կամ յուրաքանչյուր պատվերից հետո՝ առանց գումարը կանխիկացնելու և լրացուցիչ ժամանակ ծախսելու։</li>\n					<li><strong>Հարմար պատվիրում.</strong> պատվերները ձևակերպվում են հեռախոսով, էլ. փոստով կամ անմիջապես կայքի միջոցով՝ նախապես տեսնելով ապրանքի լուսանկարը, գինը և նկարագրությունը։</li>\n					<li><strong>Անվճար առաքում և 5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} զեղչ.</strong> բոլոր պայմանագրային կորպորատիվ հաճախորդների համար առաքումն անվճար է, և տրամադրվում է 5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b} զեղչի կուպոն։</li>\n					<li><strong>Համակողմանի խորհրդատվություն.</strong> մեր կորպորատիվ վաճառքների մենեջերը կօգնի ընտրել լավագույն տեսականին և ծավալները։</li>\n				</ul>\n			</article>\n\n			<article class=\"gv2-info-card gv2-glass-card\">\n				<span class=\"gv2-info-card__badge\">Միանվագ փոխանցում</span>\n				<h2>Բանկային փոխանցում առանց երկարատև պայմանագրի</h2>\n				<p>Եթե չեք ցանկանում երկարատև համագործակցության պայմանագիր կնքել, սակայն պատրաստվում եք պատվերի դիմաց վճարել բանկային փոխանցման միջոցով, ապա՝</p>\n				<ul class=\"gv2-info-list\">\n					<li>Առաքումն իրականացվում է գումարը մեր բանկային հաշվին հայտնվելուց հետո։</li>\n					<li>Պատվերի հետ տրամադրվում է համապատասխան հաշիվ-ապրանքագիրը։</li>\n					<li>Գործում են սովորական հաճախորդների համար նախատեսված առաքման պայմանները։</li>\n				</ul>\n			</article>\n		</div>\n	</section>\n\n	<!-- CTA -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-about-cta\">\n			<div class=\"gv2-about-cta__copy\">\n				<h2>Հարցերի և համագործակցության համար</h2>\n				<p>Զանգահարեք «Գայանեի Խոհանոց»-ի կորպորատիվ վաճառքների մենեջերին կամ ծանոթացեք մեր ամբողջ տեսականուն։</p>\n				<div class=\"gv2-about-cta__meta\">\n					<a href=\"tel:+37455600655\" class=\"gv2-about-cta__pill\">055 60 06 55</a>\n					<a href=\"mailto:info@gayanes.am\" class=\"gv2-about-cta__pill\">info@gayanes.am</a>\n				</div>\n			</div>\n			<div class=\"gv2-about-cta__actions\">\n				<a href=\"http://127.0.0.1:8088/shop/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-light\">\n					Explore Menu				</a>\n				<a href=\"http://127.0.0.1:8088/delivery/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-outline\">\n					Առաքում և վճարում\n				</a>\n			</div>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'corporate-clients';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'corporate-clients' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-corporate-clients.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'corporate-clients' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'corporate-clients' ON DUPLICATE KEY UPDATE `lang` = 'hy';

