UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Կարիերա</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">Թափուր աշխատատեղեր</span>\n				<h1 class=\"gv2-info-hero__title\">Կարիերա «Գայանեի Խոհանոց»-ում</h1>\n				<p class=\"gv2-info-hero__lead\">\n					Միացեք մեր ջերմ, պատասխանատու և ստեղծագործ թիմին Երևանում։ Համագործակցության և թափուր հաստիքների համար ուղարկեք Ձեր ինքնակենսագրականը (CV) <a href=\"mailto:info@gayanes.am\">info@gayanes.am</a> էլ. հասցեին։\n				</p>\n				<div class=\"gv2-info-hero__actions\">\n					<a href=\"mailto:info@gayanes.am?subject=CV{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}E2{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}94{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20Gayane&apos;s{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20Kitchen\" class=\"gv2-btn gv2-btn--primary gv2-btn--lg\">Ուղարկել CV՝ info@gayanes.am</a>\n					<a href=\"tel:+37455600655\" class=\"gv2-btn gv2-btn--glass gv2-btn--lg\">055 60 06 55</a>\n				</div>\n			</div>\n		</div>\n	</section>\n\n	<!-- Open Positions -->\n	<section class=\"gv2-section gv2-container\" aria-labelledby=\"gv2-career-jobs-heading\">\n		<div class=\"gv2-section__head\">\n			<h2 class=\"gv2-section__title\" id=\"gv2-career-jobs-heading\">Թափուր աշխատատեղեր</h2>\n		</div>\n\n		<div class=\"gv2-info-grid-3\">\n			<article class=\"gv2-job-card gv2-glass-card\">\n				<div>\n					<span class=\"gv2-info-card__badge\">Լոգիստիկա • Երևան</span>\n					<h3>Վարորդ-առաքիչ</h3>\n					<p>Փնտրում ենք վարորդ-առաքիչի, ով մեր պատրաստած համեղ կիսաֆաբրիկատները ժամանակին ու ժպիտով՝ առանց մունաթ-զունաթի, կհասցնի տեղ։</p>\n				</div>\n				<div>\n					<a href=\"mailto:info@gayanes.am?subject={1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}8E{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A4-{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BC{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}84{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}AB{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B9\" class=\"gv2-btn gv2-btn--glass\">Ուղարկել CV &rarr;</a>\n				</div>\n			</article>\n\n			<article class=\"gv2-job-card gv2-glass-card\">\n				<div>\n					<span class=\"gv2-info-card__badge\">Արտադրամաս • Դավթաշեն</span>\n					<h3>Խոհարարներ</h3>\n					<p>Աշխատանքի ենք հրավիրում ձեռքի շնորքով խոհարարների՝ պելմենի, կոտլետ, բլինչիկ, իշլի քյուֆթա և այլ մսային ու բուսական կիսաֆաբրիկատներ պատրաստելու համար։</p>\n				</div>\n				<div>\n					<a href=\"mailto:info@gayanes.am?subject={1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D4{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BD{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B8{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B0{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80\" class=\"gv2-btn gv2-btn--glass\">Ուղարկել CV &rarr;</a>\n				</div>\n			</article>\n\n			<article class=\"gv2-job-card gv2-glass-card\">\n				<div>\n					<span class=\"gv2-info-card__badge\">Բիզնեսի զարգացում</span>\n					<h3>Վաճառքի մենեջեր</h3>\n					<p>Աշխատանքի ենք հրավիրում վաճառքի մենեջերների՝ շուկայի զարգացման, կորպորատիվ համագործակցության և նոր հաճախորդների ձեռքբերման համար։</p>\n				</div>\n				<div>\n					<a href=\"mailto:info@gayanes.am?subject={1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}8E{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B3{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A1{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BC{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}84{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}AB{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B4{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}B6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}BB{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}A5{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}D6{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80\" class=\"gv2-btn gv2-btn--glass\">Ուղարկել CV &rarr;</a>\n				</div>\n			</article>\n		</div>\n	</section>\n\n	<!-- Why Join Us -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-info-grid-3\">\n			<div class=\"gv2-info-card gv2-glass-card\">\n				<h3>Կայուն և ժամանակին վարձատրություն</h3>\n				<p>Մրցունակ աշխատավարձ և աճի հնարավորություն՝ կախված Ձեր փորձից և նվիրվածությունից։</p>\n			</div>\n			<div class=\"gv2-info-card gv2-glass-card\">\n				<h3>Մաքուր և հարմարավետ խոհանոց</h3>\n				<p>Ժամանակակից սարքավորումներով և հիգիենայի բոլոր նորմերով ապահովված արտադրամաս Դավթաշենում։</p>\n			</div>\n			<div class=\"gv2-info-card gv2-glass-card\">\n				<h3>Ընկերական միջավայր</h3>\n				<p>Աշխատանք մի թիմում, որտեղ գնահատվում է յուրաքանչյուրի ձեռքի շնորքն ու բարեհամբույր վերաբերմունքը։</p>\n			</div>\n		</div>\n	</section>\n\n	<!-- CTA -->\n	<section class=\"gv2-section gv2-container\">\n		<div class=\"gv2-about-cta\">\n			<div class=\"gv2-about-cta__copy\">\n				<h2>Պատրա՞ստ եք միանալ մեր թիմին</h2>\n				<p>Ուղարկեք Ձեր CV-ն էլ. փոստով կամ զանգահարեք մեզ՝ հարցազրույց նշանակելու համար։</p>\n				<div class=\"gv2-about-cta__meta\">\n					<a href=\"mailto:info@gayanes.am\" class=\"gv2-about-cta__pill\">info@gayanes.am</a>\n					<a href=\"tel:+37455600655\" class=\"gv2-about-cta__pill\">055 60 06 55</a>\n				</div>\n			</div>\n			<div class=\"gv2-about-cta__actions\">\n				<a href=\"mailto:info@gayanes.am?subject=CV{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}E2{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}80{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}94{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20Gayane&apos;s{1dddac4d7b64a0131a4ff1ca82143894719a0abc923eaacee6f872e57ff7053b}20Kitchen\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-light\">Ուղարկել CV</a>\n				<a href=\"http://127.0.0.1:8088/about-us/\" class=\"gv2-btn gv2-btn--lg gv2-about-cta__btn-outline\">Մեր մասին</a>\n			</div>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'career';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'career' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-career.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'career' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'career' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: privacy-policy
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Գաղտնիության քաղաքականություն</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">Անձնական տվյալների պաշտպանություն</span>\n				<h1 class=\"gv2-info-hero__title\">Գաղտնիության քաղաքականություն</h1>\n				<p class=\"gv2-info-hero__lead\">\n					Սույն «Գաղտնիության քաղաքականություն»-ը նկարագրում է, թե ինչպես է «Գայանեի Խոհանոց»-ը (gayanes.am) հավաքագրում, օգտագործում և պաշտպանում Ձեր անձնական տեղեկությունները։\n				</p>\n			</div>\n		</div>\n	</section>\n\n	<section class=\"gv2-section gv2-container\">\n		<!-- Quick TOC Pills -->\n		<nav class=\"gv2-legal-toc\" aria-label=\"Բաժիններ\">\n			<a href=\"#privacy-collect\" class=\"gv2-legal-toc__pill\">01. Տեղեկությունների հավաքագրում</a>\n			<a href=\"#privacy-use\" class=\"gv2-legal-toc__pill\">02. Տեղեկությունների օգտագործում</a>\n			<a href=\"#privacy-nondisclosure\" class=\"gv2-legal-toc__pill\">03. Տվյալների չբացահայտում</a>\n			<a href=\"#privacy-security\" class=\"gv2-legal-toc__pill\">04. Հաշվի պաշտպանվածություն</a>\n		</nav>\n\n		<div class=\"gv2-legal-stack\">\n			<article id=\"privacy-collect\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">01</span>\n					<h2>Տեղեկությունների հավաքագրումը</h2>\n				</div>\n				<p>Մենք կարող ենք հավաքագրել և պահել հետևյալ անձնական տեղեկությունները.</p>\n				<ul class=\"gv2-info-list\">\n					<li>Էլ. փոստի հասցեն, անուն-ազգանունը, հեռախոսահամար(ներ)ը</li>\n					<li>Բանկային ռեկվիզիտները, եթե պատվերի համար վճարումը կատարել եք բանկային փոխանցման միջոցով։ <strong>Մենք ՉԵՆՔ տիրապետում Ձեր վճարային (կրեդիտային կամ դեբետային) քարտի որևէ տվյալի</strong>, քանի որ առցանց վճարումները մեր կայքում իրականացվում են բացառապես Arca և PayPal վճարային համակարգերի միջոցով</li>\n					<li>Կայքում Ձեր կատարած գնումների պատմությունը, նախընտրած ապրանքների ցանկը և այլն</li>\n					<li>Առաքման հասցեն(ները), առաքման համար տրամադրված լրացուցիչ ինֆորմացիան</li>\n					<li>Մեզ հետ կատարված նամակագրությունը (ներառյալ չաթը և էլեկտրոնային նամակները)</li>\n				</ul>\n			</article>\n\n			<article id=\"privacy-use\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">02</span>\n					<h2>Տեղեկությունների օգտագործումը</h2>\n				</div>\n				<p>Մեզ համար անձնական տեղեկությունների հավաքագրման առաջնային նպատակը Ձեզ ապահով, հարմարավետ, արդյունավետ և անհատական ծառայություններ մատուցելն է։ Սույնով Դուք համաձայնվում եք, որ մենք կարող ենք օգտագործել Ձեր անձնական տեղեկությունները հետևյալի համար.</p>\n				<ul class=\"gv2-info-list\">\n					<li>Ձեր հայցած ծառայությունների և օգնության ապահովում</li>\n					<li>Մեր ծառայությունների, բովանդակության և գովազդի որակի չափում և բարելավում</li>\n					<li>Ոչ ստանդարտ իրավիճակներում զանգի կամ էլ. փոստի միջոցով հավելյալ տեղեկությունների ճշտում կամ հաղորդում</li>\n					<li>Պատվերը հաստատող, սխալ լրացված դաշտերի մասին տեղեկացնող, ի պատասխան Ձեր հարցի ուղարկված և այլ տիպի էլեկտրոնային նամակների ուղարկում (օրինակ՝ պրոմո առաջարկներ, եթե բաժանորդագրված եք մեր փոստառաքման ծառայությանը)</li>\n				</ul>\n			</article>\n\n			<article id=\"privacy-nondisclosure\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">03</span>\n					<h2>Տեղեկությունների չբացահայտումը</h2>\n				</div>\n				<p>Ձեր կողմից մեզ տրամադրված տեղեկությունները համարվում են միանգամայն գաղտնի և չեն կարող տրամադրվել որևէ երրորդ կողմի։</p>\n			</article>\n\n			<article id=\"privacy-security\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">04</span>\n					<h2>Հաշվի պաշտպանվածություն</h2>\n				</div>\n				<p>Ձեր գաղտնաբառը Ձեր հաշիվ մուտք գործելու բանալին է։ Գաղտնաբառ ընտրելիս օգտագործեք թվերի, տառերի և հատուկ նիշերի չկրկնող համադրություն։ Մի՛ տվեք gayanes.am-ի Ձեր գաղտնաբառը մեկ ուրիշին. հիշե՛ք, որ Դուք պատասխանատու եք Ձեր հաշվի անունից կատարված բոլոր գործողությունների համար։</p>\n				<p>Գաղտնաբառի կորստի դեպքում այն կարող եք վերականգնել կայքի օգնությամբ՝ սեղմելով «Մուտք» կոճակի հարևանությամբ գտնվող «Մոռացել եք գաղտնաբառը» հրամանը (<a href=\"http://127.0.0.1:8088/my-account/\">Իմ հաշիվը</a>)։</p>\n			</article>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'privacy-policy';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'privacy-policy' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-privacy-policy.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'privacy-policy' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'privacy-policy' ON DUPLICATE KEY UPDATE `lang` = 'hy';

-- Page: terms
UPDATE `wp_posts` SET `post_content` = '<!-- wp:html -->\n<!-- Hero -->\n	<section class=\"gv2-info-hero\">\n		<div class=\"gv2-container\">\n			<nav class=\"gv2-about-breadcrumb\" aria-label=\"Breadcrumb\">\n				<a href=\"http://127.0.0.1:8088/\">Home</a>\n				<span aria-hidden=\"true\">/</span>\n				<span aria-current=\"page\">Օգտագործման պայմաններ</span>\n			</nav>\n\n			<div class=\"gv2-info-hero__inner\">\n				<span class=\"gv2-eyebrow\">Իրավական տեղեկատվություն</span>\n				<h1 class=\"gv2-info-hero__title\">Օգտագործման պայմաններ</h1>\n				<p class=\"gv2-info-hero__lead\">\n					Օգտվելով «Գայանեի Խոհանոց» կայքից՝ Դուք Ձեր համաձայնությունն եք տալիս ստորև շարադրված պայմաններին, ինչպես նաև մեր <a href=\"http://127.0.0.1:8088/privacy-policy/\">Գաղտնիության քաղաքականությանը</a>։ Խնդրում ենք ուշադիր կարդալ դրանք։\n				</p>\n			</div>\n		</div>\n	</section>\n\n	<section class=\"gv2-section gv2-container\">\n		<!-- Quick TOC Pills -->\n		<nav class=\"gv2-legal-toc\" aria-label=\"Բաժիններ\">\n			<a href=\"#terms-intro\" class=\"gv2-legal-toc__pill\">01. Ներածություն</a>\n			<a href=\"#terms-reg\" class=\"gv2-legal-toc__pill\">02. Գրանցում</a>\n			<a href=\"#terms-comms\" class=\"gv2-legal-toc__pill\">03. Հաղորդակցություն</a>\n			<a href=\"#terms-links\" class=\"gv2-legal-toc__pill\">04. Հղումներ</a>\n			<a href=\"#terms-returns\" class=\"gv2-legal-toc__pill\">05. Վերադարձ և փոխանակում</a>\n			<a href=\"#terms-liability\" class=\"gv2-legal-toc__pill\">06. Պատասխանատվություն</a>\n		</nav>\n\n		<div class=\"gv2-legal-stack\">\n			<article id=\"terms-intro\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">01</span>\n					<h2>Ներածություն</h2>\n				</div>\n				<p>Առաքման և վճարման հետ կապված պայմաններին կարող եք ծանոթանալ <a href=\"http://127.0.0.1:8088/delivery/\">Առաքում և վճարում</a> բաժնում։</p>\n				<p>«Գայանեի Խոհանոց» և «Մենք» տերմինները վերաբերում են սույն կայքի (այսուհետ՝ Կայք) սեփականատեր հանդիսացող «Գայանեի Խոհանոց» ընկերությանը (այսուհետ՝ Ընկերություն)։ «Դուք» տերմինը վերաբերում է այս կայքն օգտագործողներին կամ դիտողներին։</p>\n				<p>Ընկերությունն իրեն իրավունք է վերապահում ժամանակ առ ժամանակ փոփոխություններ կատարել Կայքի բովանդակության, «Գաղտնիության քաղաքականության» մեջ և սույն «Օգտագործման պայմաններում»։ Պայմանները սահմանված են և մեկնաբանվում են՝ համաձայն ՀՀ օրենսդրության։</p>\n			</article>\n\n			<article id=\"terms-reg\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">02</span>\n					<h2>Գրանցում</h2>\n				</div>\n				<p>«Գայանեի Խոհանոց»-ում գրանցվելու համար Դուք պետք է լինեք 18 տարեկանից բարձր։</p>\n				<p>Դուք հավաստում եք, որ գրանցման ժամանակ կամ դրանից հետո տրամադրված տվյալները ճշգրիտ և ամբողջական են։</p>\n			</article>\n\n			<article id=\"terms-comms\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">03</span>\n					<h2>Էլեկտրոնային նամակներ և հաղորդակցություն</h2>\n				</div>\n				<p>Երբ Դուք այցելում եք Կայք կամ մեզ էլ. փոստով նամակ եք ուղարկում, Դուք հաղորդակցվում եք մեզ հետ։ Մենք Ձեզ հետ հաղորդակցվում ենք՝ էլեկտրոնային նամակներ ուղարկելով կամ Կայքում ծանուցումներ ու տեղեկություններ տեղադրելով։ Փոխադարձ գործարքները պատշաճ ձևակերպելու նպատակով Դուք Ձեր համաձայնությունն եք տալիս՝ ստանալու մեր էլեկտրոնային հաղորդակցությունը։</p>\n				<p>«Գայանեի Խոհանոց»-ը իր հաճախորդներին ուղարկում է հետևյալ բնույթի էլեկտրոնային նամակներ.</p>\n				<ul class=\"gv2-info-list\">\n					<li>Ի պատասխան Ձեր նամակների</li>\n					<li>Պատվերը հաստատող նամակ, որում ներառված է դրա վերաբերյալ ողջ տեղեկությունը, ինչպես նաև պատվերի առաքման կամ չեղարկման վերաբերյալ նամակ</li>\n					<li>Մեր նորույթների, տարատեսակ ակցիաների վերաբերյալ նամակներ կստանաք միայն այն դեպքում, եթե բաժանորդագրված եք մեր փոստառաքման ծառայությանը։</li>\n				</ul>\n			</article>\n\n			<article id=\"terms-links\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">04</span>\n					<h2>Հղումներ</h2>\n				</div>\n				<p>Կայքում տեղադրված որոշ հղումներ կարող են տանել դեպի այլ կայքեր, որոնք «Գայանեի Խոհանոց»-ի վերահսկողության տակ չեն գտնվում։ Այսպիսի հղումներից որևէ մեկը սեղմելիս Դուք լքում եք «Գայանեի Խոհանոց» կայքը։ Սույն պայմանների կիրառությունը չի տարածվում այն կայքերի վրա, ուր Դուք տեղափոխվել եք՝ սեղմելով Կայքում տեղադրված հղումները։</p>\n			</article>\n\n			<article id=\"terms-returns\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">05</span>\n					<h2>Պատվիրված ապրանքի վերադարձ կամ փոխանակում</h2>\n				</div>\n				<p>Եթե Ձեր գնած ապրանքը չի կրել որակական և քանակային փոփոխություններ, կարող եք վերադարձնել այն 14 օրվա ընթացքում՝ ներկայացնելով ՀԴՄ կտրոնը կամ հաշիվ-ապրանքագիրը։</p>\n				<p>Եթե ապրանքը վերադարձնելու Ձեր ցանկությունը պայմանավորված է նրա որակական հատկանիշներով, Դուք կարող եք մեր առաքչի օգնությամբ փոխարինել տվյալ ապրանքը մեկ ուրիշով։ Նույնը վերաբերում է նաև այն դեպքերին, երբ սխալմամբ այլ ապրանք եք պատվիրել. գանձվում է միայն գների տարբերությունը (առկայության դեպքում), իսկ առաքման լրացուցիչ գումար չի գանձվում։</p>\n			</article>\n\n			<article id=\"terms-liability\" class=\"gv2-legal-card gv2-glass-card\">\n				<div class=\"gv2-legal-card__head\">\n					<span class=\"gv2-legal-card__num\">06</span>\n					<h2>Կայքի պատասխանատվությունը</h2>\n				</div>\n				<p>«Գայանեի Խոհանոց» կայքում տրված պատվերը իրենից ներկայացնում է Ընկերությանը Ձեր կողմից արված առաջարկ՝ գնելու և առաքման միջոցով ստանալու որևէ ապրանք։ Այդ առաջարկը համարվում է ընդունված, եթե Ձեր էլ. փոստին մեր կողմից ուղարկվում է պատվերը հաստատող նամակ, որտեղ նշված են պատվերի բոլոր մանրամասները։</p>\n				<p>Առաքման պահից սկսած ապրանքը հայտնվում է Ձեր տնօրինության տակ։ Ընկերությունն ազատվում է պատասխանատվությունից իր պարտավորությունները չկատարելու կամ հետաձգելու համար, եթե դա պայմանավորված է մեր վերահսկողությունից դուրս գտնվող պատճառներով։ Եթե սույն պայմաններից որևէ մեկը լիազոր մարմնի կողմից ճանաչվում է անվավեր, մնացած պայմանները շարունակում են վավեր համարվել։</p>\n			</article>\n		</div>\n	</section>\n<!-- /wp:html -->' WHERE `post_type` = 'page' AND `post_name` = 'terms';
DELETE pm FROM `wp_postmeta` pm INNER JOIN `wp_posts` p ON p.ID = pm.post_id WHERE p.post_type = 'page' AND p.post_name = 'terms' AND pm.meta_key = '_wp_page_template';
INSERT INTO `wp_postmeta` (`post_id`, `meta_key`, `meta_value`) SELECT `ID`, '_wp_page_template', 'page-terms.php' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'terms' LIMIT 1;
INSERT INTO `wp_gm_translations` (`group_id`, `object_type`, `object_id`, `lang`) SELECT CONCAT('gm_', UUID()), 'post', `ID`, 'hy' FROM `wp_posts` WHERE `post_type` = 'page' AND `post_name` = 'terms' ON DUPLICATE KEY UPDATE `lang` = 'hy';

